from typing import List, Tuple

def solution(input_str: str) -> str:
    """
    Solve the apartment wall removal problem.
    All rooms must be rectangular after minimum wall removals.
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:]]

    def find_rooms():
        """Find all connected components of free cells."""
        visited = [[False]*m for _ in range(n)]
        rooms = []

        for i in range(n):
            for j in range(m):
                if grid[i][j] == '.' and not visited[i][j]:
                    component = []
                    stack = [(i, j)]
                    visited[i][j] = True
                    while stack:
                        r, c = stack.pop()
                        component.append((r, c))
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < n and 0 <= nc < m:
                                if grid[nr][nc] == '.' and not visited[nr][nc]:
                                    visited[nr][nc] = True
                                    stack.append((nr, nc))
                    rooms.append(component)

        return rooms

    def is_rectangular(points):
        """Check if a set of points forms a rectangle."""
        if not points:
            return True
        rows = [p[0] for p in points]
        cols = [p[1] for p in points]
        minr, maxr = min(rows), max(rows)
        minc, maxc = min(cols), max(cols)
        expected_count = (maxr - minr + 1) * (maxc - minc + 1)
        return len(points) == expected_count

    rooms = find_rooms()

    # Check if all rooms are already rectangular
    all_rect = all(is_rectangular(rooms[i]) for i in range(len(rooms)))

    if all_rect:
        return '\n'.join(''.join(row) for row in grid)

    # Greedy approach: try to merge adjacent rooms to form rectangles
    # Collect all free cells
    all_free = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                all_free.append((i, j))

    # If all free cells already form a single rectangle, done
    if is_rectangular(all_free):
        return '\n'.join(''.join(row) for row in grid)

    # Mark all walls that separate non-rectangular regions for potential removal
    # Strategy: remove walls to make room shapes rectangular

    # Find minimal wall removals by checking connectivity
    removed = [[False]*m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*' and not removed[i][j]:
                # Check if removing this wall helps create rectangular room
                count = 0
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = i + dr, j + dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.':
                        count += 1
                if count > 0:
                    # Temporarily remove and check if rooms become rectangular
                    grid[i][j] = '.'
                    test_rooms = find_rooms()
                    if all(is_rectangular(test_rooms[k]) for k in range(len(test_rooms))):
                        removed[i][j] = True
                        for k in range(n):
                            for l in range(m):
                                if grid[k][l] != '*':
                                    # Count changes in room structure
                                    continue
                    else:
                        grid[i][j] = '*'

    # If greedy didn't work, use simpler strategy
    # Make all free cells one big rectangular room if possible
    if not all(is_rectangular(find_rooms()[k]) for k in range(len(find_rooms()))):
        # Find bounding box of all free cells
        rows = []
        cols = []
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '.':
                    rows.append(i)
                    cols.append(j)

        if rows and cols:
            minr, maxr = min(rows), max(rows)
            minc, maxc = min(cols), max(cols)
            # Remove all walls within bounding box that make it rectangular
            for i in range(minr, maxr + 1):
                for j in range(minc, maxc + 1):
                    if grid[i][j] == '*' and minr <= i <= maxr and minc <= j <= maxc:
                        grid[i][j] = '.'

    return '\n'.join(''.join(row) for row in grid)


