def solution(input_str):
    """
    Find the longest common subsequence of s1 and s2 without virus as substring.

    Args:
        input_str: String containing three lines (s1\ns2\nvirus)

    Returns:
        Longest valid common subsequence or '0' if none exists
    """
    lines = input_str.strip().split('\n')
    s1 = lines[0]
    s2 = lines[1]
    virus = lines[2]

    m, n, p = len(s1), len(s2), len(virus)

    # Precompute LPS for virus using KMP
    lps = [0] * p
    i2, length2 = 1, 0
    while i2 < p:
        if virus[i2] == virus[length2]:
            length2 += 1
            lps[i2] = length2
            i2 += 1
        else:
            if length2 != 0:
                length2 = lps[length2-1]
            else:
                lps[i2] = 0
                i2 += 1

    def kmp_next(k, c):
        """Get next virus match state after character c"""
        while k > 0 and c != virus[k]:
            k = lps[k-1]
        if c == virus[k]:
            k += 1
        return k

    # DP table: dp[i][j][k] = max LCS length using s1[:i], s2[:j] with virus state k
    INF = -10000
    dp = [[[INF] * (p + 1) for _ in range(n + 1)] for _ in range(m + 1)]

    # Parent tracking for reconstruction
    par = [[[0] * (p + 1) for _ in range(n + 1)] for _ in range(m + 1)]
    # par[i][j][k] = direction: 0=diag (match), 1=up (skip s1), 2=left (skip s2)

    # Initialize base cases
    for i in range(m + 1):
        for j in range(n + 1):
            dp[i][j][0] = 0  # State 0 is always valid for empty sequences

    # Fill DP
    for i in range(m + 1):
        for j in range(n + 1):
            for k in range(p + 1):
                if dp[i][j][k] < 0:
                    continue
                if i == m and j == n:
                    continue

                # Try diagonal (match)
                if i < m and j < n and s1[i] == s2[j]:
                    nk = k  # Match doesn't change k initially, we compute after
                    nk = kmp_next(k, s1[i])
                    if nk < p:  # Virus not complete
                        val = dp[i][j][k] + 1
                        if val > dp[i+1][j+1][nk]:
                            dp[i+1][j+1][nk] = val
                            par[i+1][j+1][nk] = 0

                # Try up (skip s1[i])
                if i < m:
                    nk = k
                    for _ in range(p):  # No change in k when skipping s1
                        if nk > 0:
                            pass
                    if i < m:
                        nk = k
                        if nk < p:
                            val = dp[i][j][nk]
                            if val > dp[i+1][j][nk]:
                                dp[i+1][j][nk] = val
                                par[i+1][j][nk] = 1

                # Try left (skip s2[j])
                if j < n:
                    nk = k
                    if nk < p:
                        if dp[i][j][nk] > dp[i][j+1][nk]:
                            dp[i][j+1][nk] = dp[i][j][nk]
                            par[i][j+1][nk] = 2

    # Find best final state
    best_len, best_k = 0, 0
    for k in range(p + 1):
        if dp[m][n][k] > best_len:
            best_len, best_k = dp[m][n][k], k

    if best_len == 0:
        return '0'

    # Reconstruct
    res = []
    i, j, k = m, n, best_k
    while i > 0 and j > 0:
        while i > 0 and j > 0:
            ok = False
            if i <= m and j <= n and par[i][j][k] == 0:
                if i > 0 and j > 0 and dp[i-1][j-1][k] + 1 == dp[i][j][k]:
                    res.append(s1[i-1])
                    nk = kmp_next(k, s1[i-1])
                    i, j = i - 1, j - 1
                    if nk < p:
                        k = nk
                    else:
                        break
                    ok = True
                    break
            elif i > 0 and j > 0 and par[i][j][k] == 1:
                if dp[i-1][j][k] == dp[i][j][k]:
                    i -= 1
                    ok = True
                    break
            elif j > 0 and par[i][j][k] == 2:
                if dp[i][j-1][k] == dp[i][j][k]:
                    j -= 1
                    ok = True
                    break
            if not ok:
                i -= 1 if j > 0 else 0
                if i == m and j > 0:
                    j -= 1
                break

    return ''.join(res[::-1]) if res else '0'
